/* The design opens the first question of every FAQ accordion and leaves the
   rest closed. The platform's `faq` widget renders plain <details> elements
   with no open-by-default option, and no behaviour marks parts inside a
   static widget, so this is the one thing here a declaration cannot say.
   The un-scripted state — every question closed — is a correct, in-flow
   layout, so the Design canvas and the first paint are both editable. */
document.querySelectorAll('.bz-faqs').forEach(function (list) {
  var first = list.querySelector('.bz-faq');
  if (first) first.open = true;
});

/* The design marks the nav item for the page you are on — accent red at 700
   where the others are #EDEDED at 600. The platform's menu block emits no
   current-page marking of any kind, so there is nothing in the markup to
   style. The un-scripted nav is the design's resting state and every item
   stays reachable, so this only adds the marker the stylesheet waits for. */
(function () {
  var here = location.pathname.replace(/\/index\.html$/, '').replace(/(.)\/$/, '$1');
  document.querySelectorAll('.bz-nav a[href]').forEach(function (a) {
    if (a.closest('.bz-subnav')) return;
    var href = a.getAttribute('href').replace(/(.)\/$/, '$1');
    if (href === here) a.setAttribute('aria-current', 'page');
  });
})();

/* --- Long-form posts: the contents rail's scroll-spy ------------------------
   Shared by every post that places the Post contents widget; on any other page
   it finds no rail and returns. */
/* The one thing the rail needs that no platform behaviour expresses.
 *
 * `filter`, `dropdown` and the rest move, show, hide and filter existing DOM;
 * none of them reads scroll position, so marking the section being read is
 * written here. Everything else the handoff asks of the table of contents is
 * already true without a script: the links are real anchors, the easing is a
 * CSS `scroll-behavior` guarded by prefers-reduced-motion, and the rail draws
 * correctly before this runs — which is what the Design canvas, the first paint
 * and a visit with JavaScript off all see.
 */
(function () {
  'use strict';

  var rail = document.querySelector('[data-bz-node="art-toc"] [data-toc]');
  if (!rail) return;

  var links = Array.prototype.slice.call(rail.querySelectorAll('.ss-toc__link'));
  var targets = links
    .map(function (link) {
      var hash = link.getAttribute('href') || '';
      return hash.charAt(0) === '#' ? document.getElementById(hash.slice(1)) : null;
    })
    .filter(Boolean);
  if (!targets.length) return;

  /* The last heading above the 40% line is the one being read. */
  function spy() {
    var line = window.innerHeight * 0.4;
    var current = null;
    targets.forEach(function (target) {
      if (target.getBoundingClientRect().top <= line) current = target.id;
    });
    links.forEach(function (link) {
      link.classList.toggle('is-current', link.getAttribute('href') === '#' + current);
    });
  }

  var ticking = false;
  window.addEventListener(
    'scroll',
    function () {
      if (ticking) return;
      ticking = true;
      window.requestAnimationFrame(function () {
        spy();
        ticking = false;
      });
    },
    { passive: true },
  );

  spy();
})();
